create table if not exists notification_policy_defaults(tenant_id text not null,kind text not null,channel text not null default 'IN_APP',enabled boolean not null default true,digest text not null default 'IMMEDIATE',quiet_hours jsonb not null default '{}',grouping_window_minutes int not null default 15,severity_threshold text not null default 'INFO',updated_by text,updated_at timestamptz not null default now(),primary key(tenant_id,kind,channel));